public class Gridness : MonoBehaviour
{
    public Sprite[] gemas; // array of gem sprites
    public int tamanoGrid; // size of the grid
    private Gem[,] grid; // 2D array to store gems
    private int score; // current score

    void Start()
    {
        grid = new Gem[tamanoGrid, tamanoGrid];
        for (int i = 0; i < tamanoGrid; i++)
        {
            for (int j = 0; j < tamanoGrid; j++)
            {
                grid[i, j] = null;
            }
